INSERT INTO prompt_definition (id, kind, display_name, description, enabled, priority, active_version, catalog_version, created_at, updated_at) VALUES ('answer.template','answer','Answer 模板','Answer 节点终态作答模板：综合上游节点输出，面向用户生成 Markdown 结论。',1,0,1,1,'2026-08-08 01:41:47','2026-08-08 01:41:47');
INSERT INTO prompt_definition (id, kind, display_name, description, enabled, priority, active_version, catalog_version, created_at, updated_at) VALUES ('compaction.summary-prompt','compaction','压缩摘要模板','ReAct 上下文压缩（Compaction）摘要模板：保留各轮思考要点，避免压缩后模型失去「先思考再行动」样例。{messages} 为待压缩对话历史占位。',1,0,1,1,'2026-08-08 01:41:47','2026-08-08 01:41:47');
INSERT INTO prompt_definition (id, kind, display_name, description, enabled, priority, active_version, catalog_version, created_at, updated_at) VALUES ('context.current-user-marker','context','上下文 · 当前提问标记','当前 user 消息前缀标记，与历史上下文块区分。',0,0,1,101,'2026-08-08 01:41:48','2026-08-21 07:26:30');
INSERT INTO prompt_definition (id, kind, display_name, description, enabled, priority, active_version, catalog_version, created_at, updated_at) VALUES ('context.l1.audit','context','L1 · 派生摘要审计','对照 L2 修订会话 mid/far；清理过期/矛盾，保留可区分有效事实。',1,0,1,1,'2026-08-08 01:41:48','2026-08-08 01:41:48');
INSERT INTO prompt_definition (id, kind, display_name, description, enabled, priority, active_version, catalog_version, created_at, updated_at) VALUES ('context.l1.far-fold','context','L1 · Far 远窗折叠','后台将更早对话折叠进 far_summary；对照现行 L2，冲突以 L2 为准，避免污染 system。',1,0,1,1,'2026-08-08 01:41:48','2026-08-08 01:41:48');
INSERT INTO prompt_definition (id, kind, display_name, description, enabled, priority, active_version, catalog_version, created_at, updated_at) VALUES ('context.l1.interrupted-marker','context','L1 · 中断注记','装载历史时对 INTERRUPTED 的 assistant 消息折叠的中断状态注记；让后续轮次从 Near 感知上一轮被中断。',1,0,1,1,'2026-08-08 01:41:48','2026-08-08 01:41:48');
INSERT INTO prompt_definition (id, kind, display_name, description, enabled, priority, active_version, catalog_version, created_at, updated_at) VALUES ('context.l1.mid-compress','context','L1 · Mid 答案压缩','后台将落入 Mid 带的 assistant 原文压成短摘要，写入 mid_answers（不改用户可见终态正文）。',1,0,1,1,'2026-08-08 01:41:48','2026-08-08 01:41:48');
INSERT INTO prompt_definition (id, kind, display_name, description, enabled, priority, active_version, catalog_version, created_at, updated_at) VALUES ('context.l2.audit','context','L2 · 状态矛盾审计','审阅用户 active L2（含 background）；明确互斥/错误 -> voidIds；暧昧矛盾 -> conflictIds；用户改主意/偏好演进不算矛盾（由写路径 UPDATE 处理）；同义跨 kind 重复不算矛盾（由规则去重处理）；仅输出 JSON。',1,0,1,150,'2026-08-08 01:41:48','2026-08-26 02:50:00');
INSERT INTO prompt_definition (id, kind, display_name, description, enabled, priority, active_version, catalog_version, created_at, updated_at) VALUES ('context.l2.extract','context','L2 · 用户状态抽取','后台从对话抽取跨会话结构化状态；仅输出 JSON 数组；低置信由运行时丢弃。',1,0,2,154,'2026-08-08 01:41:48','2026-08-27 14:35:00');
INSERT INTO prompt_definition (id, kind, display_name, description, enabled, priority, active_version, catalog_version, created_at, updated_at) VALUES ('context.l2.merge','context','L2 · 语义 merge','L2 写路径语义冲突识别（§6.4）：新候选与同 kind 既有条目语义判定（NOOP 新增 / MERGE 归一 / UPDATE 演进覆盖 / CONFLICT 双标），仅输出 JSON。',1,0,1,149,'2026-08-25 14:30:00','2026-08-25 14:30:00');
INSERT INTO prompt_definition (id, kind, display_name, description, enabled, priority, active_version, catalog_version, created_at, updated_at) VALUES ('context.memory.extract','context','Memory · KV 抽取','KV Memory 抽取：按 scope（user=用户级 / workspace=工作区级）识别可跨会话复用的结构化条目（含 todo）；v22 门禁 + 全量既有状态参照（防 key/kind/措辞漂移） + 增量输出（未变化不重复）；时间指代换算绝对日期（{today} 注入）；key 场景化、background 必填、value 自解释非布尔孤值、完成即 void、宁缺毋滥。',1,0,1,154,'2026-08-23 03:21:00','2026-08-27 14:35:00');
INSERT INTO prompt_definition (id, kind, display_name, description, enabled, priority, active_version, catalog_version, created_at, updated_at) VALUES ('context.l3.material-header','context','L3 · 历史材料边界头','注入 L3 召回材料块时的 system 边界头；标明可能过期、非指令。',1,0,1,1,'2026-08-08 01:41:48','2026-08-08 01:41:48');
INSERT INTO prompt_definition (id, kind, display_name, description, enabled, priority, active_version, catalog_version, created_at, updated_at) VALUES ('context.l3.semantic-extract','context','L3 · 语义提取','L3 v26 嵌入前语义提取层 + v26.2 body 置信门禁：按轮（turn-pair）抽取精炼语义片段（用户画像信号 / 历史任务关键结果 / 重要实时事件）；模型转述的外部知识/制度规则一律 abstain；每轮限 1~2 段；v28 改为摘要形式（合并同主题连续段落、去掉 user/assistant 零散 chunk）+ 排除 L2 已结构化覆盖内容；chat 场景 L3 仅保留 semantic 摘要层（body 原文层退役），仅输出 JSON 二维数组。',1,0,4,156,'2026-08-24 10:30:00','2026-08-27 20:30:00');
INSERT INTO prompt_definition (id, kind, display_name, description, enabled, priority, active_version, catalog_version, created_at, updated_at) VALUES ('context.layer-prompt','context','上下文分层说明','告知模型 L2/Far/Mid/Near/L3 分层用途，并强调只回答带「当前提问」标记的消息。',1,0,2,162,'2026-08-08 01:41:48','2026-08-28 09:00:00');
INSERT INTO prompt_definition (id, kind, display_name, description, enabled, priority, active_version, catalog_version, created_at, updated_at) VALUES ('context.usage-rules','context','上下文使用规则','如何使用各层上下文、冲突时以何为准。',1,0,2,163,'2026-08-08 01:41:48','2026-08-28 09:00:00');
INSERT INTO prompt_definition (id, kind, display_name, description, enabled, priority, active_version, catalog_version, created_at, updated_at) VALUES ('context.skill-directory','context','上下文 · 技能目录','可发现层：主 Agent 每轮注入租户可见技能的名+描述目录（仅摘要，正文按触发加载）；{skills} 为渲染后的名+描述列表占位。',1,0,2,147,'2026-08-24 12:00:00','2026-08-25 12:10:00');
INSERT INTO prompt_definition (id, kind, display_name, description, enabled, priority, active_version, catalog_version, created_at, updated_at) VALUES ('context.tool-directory','context','上下文 · 工具目录','工具语义检索分层注入 Tier 0：retrieval 模式下主 Agent 稳定前缀注入全量工具名+用途摘要目录；{tools} 为渲染后的名+描述列表占位。详细调用 schema 按每轮检索 Top-K 动态注入，未注入者不得臆造参数。',1,0,1,154,'2026-08-27 12:30:00','2026-08-27 12:30:00');
INSERT INTO prompt_definition (id, kind, display_name, description, enabled, priority, active_version, catalog_version, created_at, updated_at) VALUES ('conversation.title','title','会话 · 标题摘要','新对话/新任务首条消息时，用小模型提炼 15 字以内的中文短语标题。',1,0,1,1,'2026-08-08 01:41:48','2026-08-08 01:41:48');
INSERT INTO prompt_definition (id, kind, display_name, description, enabled, priority, active_version, catalog_version, created_at, updated_at) VALUES ('harness.worker','harness','Planner-Executor · Worker','Worker 单元执行薄层：单一职责（执行当前单元 + 任务摘要回传）；TaskBoard/工具调用节奏等由 mode-overlay.react 注入，工具行为以工具描述为准。',1,0,1,165,'2026-08-15 06:16:19','2026-08-28 09:00:00');
INSERT INTO prompt_definition (id, kind, display_name, description, enabled, priority, active_version, catalog_version, created_at, updated_at) VALUES ('hitl.agent-prompt','hitl','HITL Agent 提示词','人机确认（HITL）：写操作需用户确认时，向模型说明确认流程与等待态行为。',1,0,1,1,'2026-08-08 01:41:47','2026-08-08 01:41:47');
INSERT INTO prompt_definition (id, kind, display_name, description, enabled, priority, active_version, catalog_version, created_at, updated_at) VALUES ('intent.classifier.skill-agent','intent','意图收集 · 轨 A（Skill/Agent）','意图收集轨 A（fast/pro）：仅召回 agentIds/skillIds 绑定；输出不含执行模式字段，目录注入 Skill + Agent。',1,0,2,2,'2026-08-15 05:59:42','2026-08-25 04:00:00');
INSERT INTO prompt_definition (id, kind, display_name, description, enabled, priority, active_version, catalog_version, created_at, updated_at) VALUES ('intent.classifier.workflow','intent','意图收集 · 轨 B（Workflow）','意图收集轨 B（workflow）：仅召回 workflowId 绑定；输出不含执行模式字段，目录注入 Workflow。',1,0,1,1,'2026-08-15 05:59:42','2026-08-15 05:59:42');
INSERT INTO prompt_definition (id, kind, display_name, description, enabled, priority, active_version, catalog_version, created_at, updated_at) VALUES ('mode-overlay.react','mode-overlay','模式覆盖 · ReAct','ReAct 模式叠加层：约束自主推理时如何选工具、写思考与最终作答。',1,0,2,160,'2026-08-08 01:41:47','2026-08-28 09:00:00');
INSERT INTO prompt_definition (id, kind, display_name, description, enabled, priority, active_version, catalog_version, created_at, updated_at) VALUES ('mode-overlay.react-restart','mode-overlay','模式覆盖 · ReAct 继续生成','ReAct 继续生成叠加层：中断后续跑时接着已有进度，勿从头规划。',1,0,1,2,'2026-08-08 01:41:47','2026-08-12 07:14:41');
INSERT INTO prompt_definition (id, kind, display_name, description, enabled, priority, active_version, catalog_version, created_at, updated_at) VALUES ('mode-overlay.react-soft-limit','mode-overlay','ReAct · 软限额收束','ReAct 执行步数接近上限时注入的收束指令：尽快收尾、如实汇报、勿提及平台限额细节。',1,0,1,1,'2026-08-08 01:41:48','2026-08-08 01:41:48');
INSERT INTO prompt_definition (id, kind, display_name, description, enabled, priority, active_version, catalog_version, created_at, updated_at) VALUES ('mode-overlay.react-summary-turn','mode-overlay','ReAct · 收尾轮约束','总结轮（平台强制结束）注入的收尾指令：豁免工具调用、如实汇报进展、禁止 DSML/XML 泄漏与编造结果。',1,0,1,1,'2026-08-08 01:41:48','2026-08-08 01:41:48');
INSERT INTO prompt_definition (id, kind, display_name, description, enabled, priority, active_version, catalog_version, created_at, updated_at) VALUES ('mode-overlay.subagent','mode-overlay','模式覆盖 · Subagent','子 Agent 叠加层：spawn/workflow 子任务内的角色与工具使用约束。',1,0,1,109,'2026-08-08 01:41:47','2026-08-21 07:26:30');
INSERT INTO prompt_definition (id, kind, display_name, description, enabled, priority, active_version, catalog_version, created_at, updated_at) VALUES ('mode-overlay.workflow','mode-overlay','模式覆盖 · Workflow','Workflow 模式叠加层：静态/计划工作流节点执行时的补充行为约束。',1,0,1,1,'2026-08-08 01:41:47','2026-08-08 01:41:47');
INSERT INTO prompt_definition (id, kind, display_name, description, enabled, priority, active_version, catalog_version, created_at, updated_at) VALUES ('parameter-extractor.template','workflow','参数提取节点提示词模板','ParameterExtractor 节点 LLM 提示词模板；占位符 {{instruction}} {{schema}} 由运行时替换，input 作为 userContent 传入。',1,0,1,1,'2026-08-08 01:41:48','2026-08-08 01:41:48');
INSERT INTO prompt_definition (id, kind, display_name, description, enabled, priority, active_version, catalog_version, created_at, updated_at) VALUES ('planner.harness','planner','Planner-Executor · Harness Planner','Planner 独立角色：仅叠此提示词，不叠加 mode-overlay.react；最低门槛 plan_submit→dispatch_worker→self_assess→answer；通用，不含业务示例。',1,0,1,137,'2026-08-15 06:16:19','2026-08-21 07:26:30');
