INSERT INTO prompt_definition (id, kind, display_name, description, enabled, priority, active_version, catalog_version, created_at, updated_at) VALUES ('react.spawn-hint','react','ReAct · Spawn 委派提示','「$」绑定 agentIds 时注入的 spawn_subagent 委派提示；{agents} 为预定义智能体列表（- id (displayName): desc），{agentId} 为首个智能体 id。',1,0,1,98,'2026-08-08 01:41:48','2026-08-21 07:26:30');
